model FreeMinecraftServer {
  id            String   @id @default(cuid())
  userId        String   @unique
  user          User     @relation(fields: [userId], references: [id], onDelete: Cascade)
  // Public-facing name: reachable at `<subdomain>.<free_minecraft_domain>`.
  // Validated against SUBDOMAIN_RE (lib/actions-free-minecraft.ts) at creation —
  // lowercase alnum/hyphen, 3-20 chars — the same shape a DNS label allows.
  subdomain     String   @unique
  // The actual `docker run --name` on freemc-host; derived from `id` (not
  // `subdomain`) so a container is never renamed if a future feature lets a
  // player change their subdomain — the container identity and the public name
  // are deliberately decoupled.
  containerName String   @unique
  // CREATING: DB row exists, docker run hasn't been confirmed yet (worker job
  // pending/running). READY: container exists on the host — mc-router owns
  // whether it's actually awake or asleep at any given moment; we don't mirror
  // that live state here to avoid it going stale. DELETING/DELETED: teardown
  // requested/complete.
  status        String   @default("CREATING")
  // Cosmetic display name shown in the dashboard — defaults to the subdomain,
  // distinct from it so renaming never touches the connect address or the
  // container's mc-router label.
  name          String?
  // DEPRECATED — kept only for backward compatibility with the legacy
  // dashboard UI (components/customer/freemc/*.tsx) that still reads a flat
  // "preset" instead of the two-axis gameType/gameMode model below (that UI
  // is being replaced in a parallel change; do not build anything new
  // against this field). Mirrors activeGameType, EXCEPT when activeGameType
  // is "vanilla" and activeGameMode isn't "survival" — then it mirrors
  // activeGameMode instead (creative/hardcore/peaceful), matching the exact
  // flat keys the old FREEMC_PRESETS map used, so legacy cards still
  // highlight the right entry. See legacyPresetKeyFor() in
  // lib/free-minecraft-control.ts, the single place that computes it.
  preset        String   @default("vanilla")
  // Which FREEMC_GAME_TYPES key (lib/free-minecraft-control.ts) has an
  // ISOLATED, persistent world currently loaded on this server's container —
  // drives the itzg `LEVEL` env var at container-recreate time, so each game
  // type's world lives in its own `<LEVEL>`/`<LEVEL>_nether`/`<LEVEL>_the_end`
  // folder set inside the SAME /data volume mount and switching types never
  // touches another type's saved world again (fixes the 2026-08-25 incident
  // where a SkyBlock->Vanilla switch corrupted the one shared world — see
  // lib/actions-freemc-worlds.ts). One FreeMinecraftWorld row exists per
  // game type this account has ever actually visited.
  activeGameType String  @default("vanilla")
  // Which FREEMC_GAME_MODES key (survival/hardcore/creative/peaceful) is
  // layered on top of activeGameType's world as a server.properties overlay
  // (gamemode/hardcore/difficulty). Applied via RCON + a restart of the SAME
  // container — never a world switch, never touches activeGameType's data.
  activeGameMode String  @default("survival")
  // One row per game type this account has ever applied (created lazily on
  // first visit, NOT pre-created for all 9 types) — powers the world list
  // (list/rename/last-played) in the dashboard. See
  // lib/actions-freemc-worlds.ts.
  worlds        FreeMinecraftWorld[]
  createdAt     DateTime @default(now())

  // ---- Public server directory (opt-in) ----
  // Off by default — a server is only ever listed/joinable-by-strangers if the
  // owner explicitly flips this in Manage. Directory join-instructions and the
  // server's own marketing page both gate on this flag server-side, not just
  // hiding the UI, so a stale link can never leak a private server's address.
  isPublic          Boolean  @default(false)
  publicTagline     String? // short one-liner shown on the directory card
  publicDescription String? // longer body shown on the server's own page

  // ---- Mod menu ----
  // Extra Modrinth plugin slugs layered on top of the active preset's own
  // env.MODRINTH_PROJECTS at container-recreate time (lib/free-minecraft-control
  // `propertiesToEnv`/recreatePresetContainer). Only meaningful for a
  // kind:"plugins" preset — a properties-only preset has nowhere to put a
  // plugin jar. Deliberately just slugs, not full env strings: this list is
  // validated against a fixed catalog before it ever reaches a docker command.
  extraMods         String[] @default([])
}
model FreeMinecraftWorld {
  id           String              @id @default(cuid())
  serverId     String
  server       FreeMinecraftServer @relation(fields: [serverId], references: [id], onDelete: Cascade)
  gameType     String // FREEMC_GAME_TYPES key (lib/free-minecraft-control.ts)
  label        String? // customer-chosen display name; defaults to the type's own label when unset
  lastPlayedAt DateTime?
  createdAt    DateTime            @default(now())

  @@unique([serverId, gameType])
}
model GameSchedule {
  id              String    @id @default(cuid())
  serverId        String
  server          Server    @relation(fields: [serverId], references: [id], onDelete: Cascade)
  // "restart" = power-cycle the server; "command" = send an RCON command.
  kind            String    @default("restart")
  // RCON command to run (only for kind="command", e.g. "save-all").
  command         String?
  hour            Int // 0..23 (UTC) — used for daily (non-interval) schedules
  minute          Int // 0..59
  // If set, run every N minutes instead of daily at hour:minute.
  intervalMinutes Int?
  enabled         Boolean   @default(true)
  // Warn connected players over RCON before the restart (games that support it).
  announce        Boolean   @default(true)
  lastRunAt       DateTime?
  nextRunAt       DateTime?
  createdAt       DateTime  @default(now())
  updatedAt       DateTime  @updatedAt

  @@index([enabled, nextRunAt])
  @@index([serverId])
}
model GamePlan {
  id           String   @id @default(cuid())
  gameFamily   String // minecraft, valheim, rust, palworld, cs2, terraria, ...
  name         String // e.g. "Minecraft — 4 GB / 20 slots"
  ramMB        Int
  cpuCores     Int      @default(2)
  diskGB       Int
  slots        Int? // player slots (nullable)
  priceCents   Int // retail price the customer pays (per term)
  termMonths   Int      @default(1)
  basePlanId   String // the VPS Plan used to size/provision the VM
  basePlan     Plan     @relation(fields: [basePlanId], references: [id])
  osTemplateId String? // the game's OsTemplate (image) to deploy
  featured     Boolean  @default(false)
  active       Boolean  @default(true)
  sortOrder    Int      @default(0)
  createdAt    DateTime @default(now())
  servers      Server[]
}
model GameMod {
  id               String      @id @default(cuid())
  gameFamily       String // minecraft, rust, valheim, cs2, ark-ase, ark-asa, palworld, terraria, project-zomboid, ...
  name             String
  slug             String // stable per-family kebab identifier
  category         String // Admin, Protection, Economy, Performance, Content, QoL, ...
  // Where it comes from + how the installer fetches it. One of: modrinth, curseforge,
  // hangar, spigotmc, steam_workshop, thunderstore, umod, codefling, nexus, ficsit,
  // rocketmod, factorio_portal, mcpedl, github, manual.
  source           String
  sourceId         String? // workshop id / curseforge project id / modrinth slug / etc.
  url              String?
  modStringId      String? // e.g. Project Zomboid's Mods= string id (distinct from the numeric Workshop id)
  appliesToVariant String? // restrict to a loader/variant (e.g. "paper", "oxide", "carbon"); null = any
  description      String?
  iconUrl          String?
  popularity       Int         @default(0) // higher = more popular (sort key)
  paid             Boolean     @default(false)
  featured         Boolean     @default(false)
  active           Boolean     @default(true)
  createdAt        DateTime    @default(now())
  updatedAt        DateTime    @updatedAt
  installs         ServerMod[]

  @@unique([gameFamily, slug])
  @@index([gameFamily, category])
}

model Server {
  id                  String           @id @default(cuid())
  name                String
  label               String? // customer-facing nickname (rename)
  // Set when this order arrived via a partner deep link (?ref=kodely on
  // /dashboard/deploy, captured by PartnerSourceCapture). Null for every direct
  // Nxeon order. Gates the webhook notify in worker/index.ts on provision success.
  partnerSource       String?
  hostname            String
  vmid                Int?             @unique
  status              ServerStatus     @default(PENDING)
  ipAddress           String?          @unique
  sshPort             Int?             @unique
  rootPassword        String?
  rootPasswordEnc     String?
  isFree              Boolean          @default(false)
  autoRenew           Boolean          @default(true)
  gameVariant         String? // game-server type/loader (e.g. paper, carbon, bepinex) — see lib/game-config
  gameConfig          Json? // per-game settings values (validated against the family schema)
  // Minecraft-only: `<subdomain>.play.nxeon.cloud`, resolved via a per-server DNS
  // SRV record (worker/game-subdomain.ts) instead of the free tier's shared
  // mc-router — see lib/game-subdomain.ts for the shared name-validation rules.
  // Null until the customer sets one; unique across THIS column only — cross-
  // checked against FreeMinecraftServer.subdomain at the application layer since
  // Postgres can't enforce a unique constraint across two different tables.
  subdomain           String?          @unique
  suspendedNote       String?
  // WHY a server is suspended: "UNPAID" | "ABUSE" | "ADMIN". Null = never suspended.
  //
  // `suspendedNote` used to be the only signal, and nothing consumed it, so every
  // suspension looked identical to the billing engine. Two live consequences:
  // (1) `terminateOverdue` selected on `status: "SUSPENDED"` alone, while the
  //     renewal sweep EXCLUDES suspended servers — so an admin suspending a
  //     paid-up customer pending an investigation meant they were never charged,
  //     never warned, their term lapsed, and 13 days later their VM and all its
  //     data were destroyed with a "prolonged non-payment" notice they had never
  //     been given a chance to act on.
  // (2) `renewNow` auto-unsuspended ANY suspended server on payment, so a spammer
  //     suspended for outbound abuse could pay and put themselves straight back
  //     on the network.
  // Both now scope strictly to UNPAID.
  suspendReason       String?
  // Human-readable reason a PROVISION failed terminally, set by the worker on the
  // ERROR path (worker/index.ts). Surfaced on the server detail page's ERROR
  // banner so the customer sees WHAT went wrong instead of a bare red status dot.
  // Cleared when a retry re-enqueues provisioning. Null = never failed (or the
  // failure predates this column).
  provisionError      String?
  // Best-effort, human-readable label for whichever real provisioning phase is
  // running RIGHT NOW (e.g. "Cloning your server…", "Waiting for the game server
  // to start…") — written by worker/index.ts's provision() between real,
  // observable checkpoints (clone / config / start / guest-agent boot / SSH
  // reachable / game port open). Read by lib/provisioning-step.ts and shown by
  // <ProvisioningOverlay/> in place of its cosmetic time-based cycling text.
  // Null = no real signal available yet (falls back to the cosmetic text) or the
  // server isn't mid-provision. Never cleared explicitly — it's simply ignored
  // once status leaves PENDING/PROVISIONING.
  provisioningStep    String?
  expiresAt           DateTime?
  // ---- Dunning (failed auto-charge retry state) ----
  // dunningStage counts CARD ATTEMPTS THAT HAVE FAILED for the current unpaid
  // period: 0 = nothing owed / paid, 1..N = that many failures. Reset to 0 the
  // moment a renewal succeeds. `dunningNextAt` gates the next retry so a
  // 5-minute billing sweep cannot burn every retry in a quarter of an hour, and
  // `dunningPayUrl` is a hosted Checkout link emailed to the customer so they can
  // clear the balance themselves (also how 3-D Secure challenges are satisfied).
  dunningStage        Int              @default(0)
  dunningNextAt       DateTime?
  dunningPayUrl       String?
  // Sent-marker for the pre-renewal "no card on file" reminder (worker/billing.ts
  // renewalReminderSweep). Set to `now` when a card-less owner is reminded that a
  // paid server is about to renew, and reset to null when that period actually
  // renews (commitRenewal), so each cycle can remind at most once. Null = not yet
  // reminded this cycle.
  renewalReminderSentAt DateTime?
  createdAt           DateTime         @default(now())
  updatedAt           DateTime         @updatedAt
  userId              String
  user                User             @relation(fields: [userId], references: [id])
  nodeId              String?
  node                Node?            @relation(fields: [nodeId], references: [id])
  bwInBytes           BigInt           @default(0)
  bwOutBytes          BigInt           @default(0)
  abuseBwMark         BigInt? // last bwOutBytes sample, for outbound-rate abuse detection
  abuseBwMarkAt       DateTime? // when abuseBwMark was taken
  bwWindowStart       DateTime         @default(now())
  termMonths          Int              @default(1) // 1=monthly, 12=annual, 24=biennial, 36=triennial
  /// PERCENT OFF the term-discounted monthly rate that the months currently sitting
  /// between `now` and `expiresAt` were ACTUALLY sold at. This is the rate basis
  /// every proration must price against (lib/proration.ts).
  ///
  /// WHY IT EXISTS (2026-07-26). `prorateDeltaCents` defaulted its rate basis to
  /// `currentPromo(now)` — whatever seasonal promo happened to be running at the
  /// instant a resize was priced. Promos rotate by calendar date from a 15% Launch
  /// Sale to 45% for Cyber Monday, so a customer could upgrade during Cyber Monday
  /// (delta priced at 55% of the honest rate, small charge) and downgrade during
  /// the Launch Sale (delta priced at 85%, large credit) and pocket the 30-point
  /// spread x plan delta x every remaining month — repeatable every promo cycle,
  /// self-service, with the platform's own marketing calendar as the schedule.
  /// lib/promotions.ts is explicit that a promo is a FIRST-TERM intro discount that
  /// renewals never receive, so pricing a mid-term change off today's promo was
  /// wrong even before it was exploitable.
  ///
  /// WHY A PERCENT AND NOT A CENTS RATE. Proration is a DIFFERENCE between two
  /// plans' rates. A stored $/mo figure prices only the plan the server is on and
  /// says nothing about the plan it is moving to, so the other half of the
  /// subtraction would still need a basis invented for it — which is the bug. A
  /// percent is a rate BASIS that applies to any plan price, so both halves of the
  /// delta come from this one persisted number and the round trip is symmetric by
  /// construction rather than by convention. It also survives a plan change with no
  /// write at all: the customer keeps the rate they bought at, so up-then-down is
  /// exactly zero.
  ///
  ///   0   = full price. What BOTH renewal paths bill (worker/billing.ts sweep and
  ///         lib/actions.ts renewNow charge `vpsTermPriceCents` with no promo), and
  ///         what a flat-priced game plan is sold at.
  ///   1-99= a genuine intro/seasonal discount, or a blend of paid and gifted
  ///         months (see prorateBlendPercent in lib/proration.ts).
  ///   100 = gifted. Nothing was paid for these months, so nothing may prorate out
  ///         of them — an admin extension/free grant records this.
  ///   NULL= unknown. Only on rows that predate this column; resolved by an
  ///         EXPLICIT conservative fallback (`resolveTermPromoPercent`), never by
  ///         falling through to today's promo, because that IS the bug above.
  ///
  /// FLOAT, not Int, even though every promo in the catalogue is a whole number.
  /// Blending a renewal into a part-used term lands on halves: 36 months at 45% off
  /// plus 36 renewed at full price is exactly 22.5% off, and rounding that to 23
  /// quietly shaves $7.20 off a $1,071.36 credit. A first term still stores the
  /// promo's exact integer, so the column reads the same for the common case.
  termPromoPercent    Float?
  /// PERCENT the ANNUAL (12-month) commitment discount was set to when THIS server's
  /// term was sold — a snapshot of `annual_discount_percent` (lib/annual-discount.ts)
  /// frozen at the moment of sale, exactly like `termPromoPercent` freezes the seasonal
  /// rate.
  ///
  /// WHY IT EXISTS. The annual discount became an admin-configurable setting, read LIVE
  /// by proration (lib/proration.ts, via `vpsEffectiveMonthly`). Both halves of a resize
  /// round trip therefore priced against whatever the setting held at the instant each
  /// half ran: an admin nudging `annual_discount_percent` between a customer's upgrade
  /// and their downgrade made the credit and the charge disagree, so an annual server's
  /// up-then-down no longer netted to zero. Freezing the rate the server was SOLD at and
  /// reading THAT from both proration directions makes the round trip symmetric by
  /// construction, the same way `termPromoPercent` does for the promo rate.
  ///
  ///   NULL = pre-existing row (predates this column) OR a non-annual/flat-priced server
  ///          that never had an annual discount. Proration falls back to the LIVE setting
  ///          for these — identical maths for every non-annual term, and the best
  ///          available basis for a legacy annual row.
  annualDiscountPct   Float?
  /// The PLAN-portion cash actually collected for this term at the moment of sale,
  /// in cents, NET of promo AND coupon and EXCLUDING recurring add-ons (dedicated IP,
  /// extra disk, paid backups). This is the authoritative basis for a cancellation
  /// refund: `terminationRefundCents` prorates THIS over the unused months rather than
  /// recomputing from list price × `termPromoPercent` — which lies (currentPromo stamps
  /// 100 even on a full-price VPS, zeroing the refund) and is coupon-blind (a coupon
  /// reduces cash collected but never `termPromoPercent`, so the old basis over-refunded
  /// the coupon amount). Storing the real cash makes the refund exact and provably
  /// ≤ paid. NULL = row predates this column → refund falls back to the conservative
  /// `termPromoPercent` formula (never over-refunds; $0 for the 100-stamped common case).
  /// Left at its first-term value across renewals (renewals charge FULL price, so the
  /// stored first-term net is ≤ what any later term collected → still never over-refunds).
  refundableTermCents Int?
  /// GB of root disk purchased BEYOND the plan's `diskGB`. The server's EFFECTIVE
  /// disk is always `plan.diskGB + extraDiskGB`, so the extra survives a plan
  /// resize (it is additive to whichever plan the server sits on). Growth is
  /// ONE-WAY: shrinking a live filesystem risks data loss, so nothing anywhere
  /// in the platform ever decrements this field.
  extraDiskGB         Int              @default(0)
  addons              Json             @default("{}") // { malwareScanner, dailyBackup, docker }
  dedicatedIp         DedicatedIp?
  wantsDedicatedIp    Boolean          @default(false)
  projectId           String?
  project             Project?         @relation(fields: [projectId], references: [id], onDelete: SetNull)
  planId              String
  plan                Plan             @relation(fields: [planId], references: [id])
  osTemplateId        String
  osTemplate          OsTemplate       @relation(fields: [osTemplateId], references: [id])
  jobs                Job[]
  portForwards        PortForward[]
  firewallRules       FirewallRule[]
  autoUpdate          Boolean          @default(false) // game-server auto-update opt-in
  claudeBuilds        ClaudeBuild[]
  gamePlanId          String?
  gamePlan            GamePlan?        @relation(fields: [gamePlanId], references: [id])
  ipv6                String? // assigned IPv6 address
  autoBackup          Boolean          @default(false)
  backupIntervalHours Int? // scheduled-backup cadence
  lastAutoBackup      DateTime?
  // Paid backup RETENTION tier (lib/backup-tiers.ts). Single source of truth for
  // what the customer bought + is charged. `backupKeep` is the RESOLVED retention
  // the worker enforces (worker/index.ts backupCreate); null falls back to the
  // tier default so an admin can retune tier->keep centrally without a migration.
  backupTier          BackupTier       @default(FREE)
  backupKeep          Int?
  volumes             Volume[]
  websites            Website[]
  vpsDatabases        VpsDatabase[]
  appInstalls         AppInstall[]
  cronJobs            CronJob[]
  boardApps           App[]
  // Set the moment the post-purchase "leave us a review" email is sent for this
  // server, so the worker sends it exactly once per order even if a PROVISION job
  // is retried. Null = never sent (or profile URLs weren't configured yet).
  reviewRequestSentAt DateTime?
  // When this VM is the backing box for a managed Nextcloud (NxCloud), the
  // companion row that carries the subdomain, admin creds, and app status. Null
  // for an ordinary VPS. The VM itself is a normal Server — it renews, duns,
  // suspends and monitors through the exact same audited machinery.
  nxcloudInstance     NxCloudInstance?
  // Game control panel: customer-defined automatic-restart schedules (worker sweep
  // enqueues a GAME_POWER restart at each due time). Cascade so they vanish with
  // the server.
  gameSchedules       GameSchedule[]
  mods                ServerMod[]
  publicListing       Boolean          @default(false)
  publicDescription   String?
  customDomain          String?
  customDomainVerified  Boolean          @default(false)
  playerSessions      PlayerSession[]
  // ---- Live telemetry (nxeon-shipper agent) ----
  // Bearer token the per-server shipper agent authenticates ingest requests
  // with. Same convention as PasswordResetToken/API keys elsewhere: only the
  // SHA-256 hash is stored, the raw token is minted once at provision time,
  // baked into the cloud-init config, and never persisted in the clear. Null
  // until the server's first (re)provision after this feature shipped.
  telemetryTokenHash  String?          @unique
  telemetryEvents     TelemetryEvent[]
}
model ServerMod {
  id          String   @id @default(cuid())
  serverId    String
  server      Server   @relation(fields: [serverId], references: [id], onDelete: Cascade)
  modId       String
  mod         GameMod  @relation(fields: [modId], references: [id])
  status      String   @default("INSTALLING") // INSTALLING | INSTALLED | FAILED | REMOVING | REMOVED
  version     String?
  error       String? // last failure detail, surfaced in the portal
  installedAt DateTime @default(now())
  updatedAt   DateTime @updatedAt

  @@unique([serverId, modId])
  @@index([serverId])
}
enum ServerStatus {
  PENDING
  PROVISIONING
  RUNNING
  STOPPED
  SUSPENDED
  REINSTALLING
  DELETING
  ERROR
}
model Job {
  id        String    @id @default(cuid())
  type      JobType
  status    JobStatus @default(QUEUED)
  payload   Json?
  error     String?
  progress  Int       @default(0) // 0..100 live task progress (backups/restores)
  step      String? // human-readable current step, e.g. "Creating archive… 42%"
  attempts  Int       @default(0)
  serverId  String?
  server    Server?   @relation(fields: [serverId], references: [id], onDelete: Cascade)
  createdAt DateTime  @default(now())
  updatedAt DateTime  @updatedAt
}
enum JobType {
  PROVISION
  START
  STOP
  REBOOT
  REINSTALL
  DELETE
  SUSPEND
  UNSUSPEND
  RESIZE
  SNAPSHOT_CREATE
  SNAPSHOT_DELETE
  SNAPSHOT_ROLLBACK
  BACKUP_CREATE
  BACKUP_RESTORE
  SYNC_FORWARDS
  SYNC_FIREWALL
  SYNC_GAME_DNS // keep worker/game-subdomain-sync.ts's syncGameServerDns in sync with the server's actual ip:port
  PASSWORD_RESET
  CLAUDE_BUILD
  GAME_UPDATE
  VOLUME_CREATE
  VOLUME_ATTACH
  VOLUME_DETACH
  VOLUME_DELETE
  GAME_CONFIG
  SSL_ISSUE
  MIGRATE
  WEBSITE_CREATE
  WEBSITE_DELETE
  WEBSITE_TOGGLE
  WEBSITE_SSL
  SITE_PUBLISH
  SITE_UNPUBLISH
  DB_CREATE
  DB_DELETE
  APP_INSTALL
  CRON_SYNC
  SERVICE_ACTION
  DISK_EXPAND
  // Post-deploy dedicated-IP add-on for an already-provisioned server (VPS or
  // game) that didn't have one — lib/dedicated-ip-purchase.ts + worker/index.ts.
  ASSIGN_DEDICATED_IP
  // Game server control panel (worker/game-control.ts).
  GAME_POWER // start / stop / restart the game SERVICE (distinct from VM power)
  GAME_BACKUP // archive the game's world/save dir into a downloadable backup
  GAME_MOD_SYNC // reconcile the server's installed mods (install INSTALLING, remove REMOVING)
}
enum JobStatus {
  QUEUED
  RUNNING
  DONE
  FAILED
}
