function PowerConsole({ serverId, view }: { serverId: string; view: GameManageView }) {
  const [lines, setLines] = useState<string[]>([]);
  const [logErr, setLogErr] = useState<string | null>(null);
  const [cmd, setCmd] = useState("");
  const [feed, setFeed] = useState<string[]>([]);
  const [msg, setMsg] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const [sending, startSend] = useTransition();
  const logBox = useRef<HTMLPreElement>(null);

  const refreshLogs = useCallback(() => {
    getGameLogs(serverId).then((r) => {
      if (r.ok) {
        setLines(r.lines);
        setLogErr(null);
      } else setLogErr(r.error);
    });
  }, [serverId]);

  useEffect(() => {
    if (!view.running) return;
    refreshLogs();
    const t = setInterval(refreshLogs, 8000);
    return () => clearInterval(t);
  }, [view.running, refreshLogs]);

  useEffect(() => {
    if (logBox.current) logBox.current.scrollTop = logBox.current.scrollHeight;
  }, [lines]);

  function power(action: "start" | "stop" | "restart") {
    start(async () => {
      setMsg(null);
      const r = await gamePower(serverId, action);
      setMsg(r.ok ? `${action[0].toUpperCase()}${action.slice(1)} requested — watch the console for progress.` : r.error);
    });
  }

  function send() {
    const c = cmd.trim();
    if (!c) return;
    startSend(async () => {
      const r = await sendGameCommand(serverId, c);
      setFeed((f) => [...f.slice(-40), `> ${c}`, r.ok ? r.response || "(no output)" : `! ${r.error}`]);
      setCmd("");
    });
  }

  return (
    <div className="space-y-6">
      <div className="card">
        <h3 className="font-semibold">Game service power</h3>
        <p className="mt-1 text-sm text-slate-400">
          Starts, stops or restarts the game process itself — separate from powering the whole VM off.
        </p>
        <div className="mt-4 flex flex-wrap gap-2">
          <button className="btn-primary" disabled={pending || !view.running} onClick={() => power("start")}>
            Start
          </button>
          <button className="btn-secondary" disabled={pending || !view.running} onClick={() => power("restart")}>
            Restart
          </button>
          <button className="btn-secondary" disabled={pending || !view.running} onClick={() => power("stop")}>
            Stop
          </button>
        </div>
        {msg && <p className="mt-3 text-sm text-slate-300">{msg}</p>}
      </div>

      <div className="card">
        <div className="flex items-center justify-between">
          <h3 className="font-semibold">Live console</h3>
          <button className="text-xs text-slate-400 hover:text-white" onClick={refreshLogs} disabled={!view.running}>
            Refresh
          </button>
        </div>
        {logErr && <p className="mt-2 text-sm text-amber-300">{logErr}</p>}
        <pre
          ref={logBox}
          className="mt-3 max-h-80 overflow-auto rounded-xl border border-white/[0.06] bg-navy-950/80 p-3 font-mono text-[11px] leading-relaxed text-slate-300"
        >
          {lines.length ? lines.join("\n") : view.running ? "Waiting for logs…" : "Start the server to see logs."}
        </pre>

        {feed.length > 0 && (
          <pre className="mt-3 max-h-48 overflow-auto rounded-xl border border-brand-500/20 bg-navy-950/60 p-3 font-mono text-[11px] leading-relaxed text-slate-300">
            {feed.join("\n")}
          </pre>
        )}

        <div className="mt-3 flex gap-2">
          <input
            className="input flex-1 font-mono text-xs"
            placeholder={
              view.rconSupported ? "Type a console/RCON command (e.g. say hello)…" : "Console commands are not available for this game"
            }
            value={cmd}
            disabled={!view.rconSupported || sending || !view.running}
            onChange={(e) => setCmd(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && send()}
          />
          <button className="btn-primary" disabled={!view.rconSupported || sending || !view.running || !cmd.trim()} onClick={send}>
            {sending ? "Sending…" : "Send"}
          </button>
        </div>
        {!view.rconSupported && (
          <p className="mt-2 text-xs text-slate-500">
            The command box is disabled because this game has no wired remote-console protocol.
          </p>
        )}
      </div>
    </div>
  );
}

