    if (!/^[a-z_][a-z0-9_:]{1,80}$/.test(itemId)) return { ok: false, error: "Invalid item ID." };
    const n = Math.max(1, Math.min(64, Math.trunc(count) || 1));
    return await mcRcon(serverId, `give ${v.name} ${itemId} ${n}`, "gameserver.give", `${v.name} ${itemId} x${n}`);
  } catch (err) { return { ok: false, error: safeError(err) }; }
