export async function applyGameInventoryEdit(
  serverId: string,
  playerName: string,
  edits: { slot: string; itemId: string; count: number }[]
): Promise<{ ok: true; results: { slot: string; ok: boolean; error?: string }[] } | { ok: false; error: string }> {
  try {
    const v = validMcName(playerName);
    if (!v.ok) return v;
    if (!edits.length) return { ok: false, error: "No edits provided." };
    if (edits.length > 50) return { ok: false, error: "Too many edits at once (max 50)." };
    const results: { slot: string; ok: boolean; error?: string }[] = [];
    for (const edit of edits) {
      if (!/^[a-z_.0-9]+$/i.test(edit.slot)) {
        results.push({ slot: edit.slot, ok: false, error: "Invalid slot." });
        continue;
      }
      if (!/^[a-z_][a-z0-9_:]{1,80}$/.test(edit.itemId)) {
        results.push({ slot: edit.slot, ok: false, error: "Invalid item." });
        continue;
      }
      const n = Math.max(1, Math.min(64, Math.trunc(edit.count) || 1));
      // MUST be namespaced "minecraft:item", not bare "item" — on Paper/Purpur
      // servers with EssentialsX installed, the plugin registers its own
      // "item" command which silently swallows the bare form (it parses
      // "replace" as a nonexistent item id and no-ops since the RCON sender
      // isn't a player). The "minecraft:" prefix forces vanilla dispatch
      // regardless of what a plugin has registered — see the identical,
      // live-verified fix and root-cause note in
      // lib/actions-freemc-inventory.ts (free-tier equivalent).
      const cmd = `minecraft:item replace entity ${v.name} ${edit.slot} with ${edit.itemId} ${n}`;
      const r = await mcRcon(serverId, cmd, "gameserver.inventory", `${v.name} ${edit.slot} → ${edit.itemId} x${n}`);
      // Transport success alone doesn't mean the game accepted the command —
      // Minecraft reports failures (bad slot/item/offline target) as plain
      // response TEXT over a normally-successful RCON round trip, so check
      // the response body, not just the RCON transport's ok flag.
      if (!r.ok) {
        results.push({ slot: edit.slot, ok: false, error: r.error });
      } else if (/unknown|no entity was found|invalid|cannot|not found|expected/i.test(r.response)) {
        results.push({ slot: edit.slot, ok: false, error: r.response.trim() || "Command failed." });
      } else {
        results.push({ slot: edit.slot, ok: true });
      }
    }
    return { ok: true, results };
  } catch (err) { return { ok: false, error: safeError(err) }; }
}

