export type GameBackupRow = BackupEntry & { downloadUrl: string };

export async function getGameBackups(
  serverId: string
): Promise<{ ok: true; backups: GameBackupRow[] } | { ok: false; error: string }> {
  try {
    const { user, server } = await ownedServer(serverId);
    requireSpec(server);
    const limited = throttle(user.id, "backups", 30);
    if (limited) return { ok: false, error: limited };
    const toRow = (b: BackupEntry): GameBackupRow => ({
      ...b,
      downloadUrl: `/api/files/${serverId}?path=${encodeURIComponent(b.path)}&download=1`,
    });
    if (SANDBOX) {
      const b: BackupEntry = {
        name: "minecraft-20260812-020000.tar.gz",
        path: "/var/backups/nxeon-game/minecraft-20260812-020000.tar.gz",
        sizeBytes: 51_204_884,
        modifiedMs: Date.now() - 3_600_000,
      };
      return { ok: true, backups: [toRow(b)] };
    }
    if (server.status !== "RUNNING")
      return { ok: false, error: "Backups are listable only while the server is running." };
    const res = await withServerSsh(server as SftpServer, (conn) => readGameBackups(conn));
    return res.ok ? { ok: true, backups: res.backups.map(toRow) } : { ok: false, error: res.error };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function createGameBackup(serverId: string): Promise<Result> {
  try {
    const { user, server } = await ownedServer(serverId);
    requireSpec(server);
    const limited = throttle(user.id, "backup-create", 6);
    if (limited) return { ok: false, error: limited };
    if (server.status !== "RUNNING")
      return { ok: false, error: "The VM must be running to back up the world." };
    if (await lifecycleBusy(server.id))
      return { ok: false, error: "Another server operation is in progress — try again shortly." };
    if (await gameJobInflight(server.id))
      return { ok: false, error: "A game control action is already in progress on this server." };

    await db.job.create({ data: { type: "GAME_BACKUP", serverId: server.id, payload: {} } });
    await db.auditLog.create({
      data: { userId: user.id, action: "gameserver.backup", detail: `world backup on ${server.hostname}` },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

// ---------------------------------------------------------------------------
// Scheduled tasks (GameSchedule CRUD) — restarts + RCON commands
// ---------------------------------------------------------------------------

export type ScheduleRow = {
  id: string;
  kind: string;
  command: string | null;
  hour: number;
  minute: number;
  intervalMinutes: number | null;
  enabled: boolean;
  announce: boolean;
  nextRunAt: string | null;
  lastRunAt: string | null;
};

function rowOut(s: {
  id: string;
  kind: string;
  command: string | null;
  hour: number;
  minute: number;
  intervalMinutes: number | null;
  enabled: boolean;
  announce: boolean;
  nextRunAt: Date | null;
  lastRunAt: Date | null;
}): ScheduleRow {
  return {
    id: s.id,
    kind: s.kind,
    command: s.command,
    hour: s.hour,
    minute: s.minute,
    intervalMinutes: s.intervalMinutes,
    enabled: s.enabled,
    announce: s.announce,
    nextRunAt: s.nextRunAt ? s.nextRunAt.toISOString() : null,
    lastRunAt: s.lastRunAt ? s.lastRunAt.toISOString() : null,
  };
}

/** Compute the next run for an interval-based schedule. */
function computeNextInterval(intervalMinutes: number, from: Date = new Date()): Date {
  return new Date(from.getTime() + intervalMinutes * 60_000);
}

function validTime(hour: number, minute: number): boolean {
  return Number.isInteger(hour) && hour >= 0 && hour <= 23 && Number.isInteger(minute) && minute >= 0 && minute <= 59;
}

/** Cap on schedules per server (a daily restart or three is the realistic case). */
const MAX_SCHEDULES = 8;

export async function listGameSchedules(
  serverId: string
): Promise<{ ok: true; schedules: ScheduleRow[] } | { ok: false; error: string }> {
  try {
    const { server } = await ownedServer(serverId);
    requireSpec(server);
    const rows = await db.gameSchedule.findMany({ where: { serverId }, orderBy: [{ kind: "asc" }, { hour: "asc" }, { minute: "asc" }] });
    return { ok: true, schedules: rows.map(rowOut) };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

// SCHEDULE_COMMANDS + SCHEDULE_COMMAND_LIST live in lib/game-schedule-commands.ts
// — a plain (non-"use server") module; see that file's header comment.

const ALLOWED_INTERVALS = [5, 15, 30, 60, 360, 720, 1440] as const;
export type AllowedInterval = (typeof ALLOWED_INTERVALS)[number];

export async function createGameSchedule(
  serverId: string,
  hour: number,
  minute: number,
  announce: boolean,
  opts?: { kind?: "restart" | "command"; command?: string; intervalMinutes?: number }
): Promise<Result> {
  try {
    const { user, server } = await ownedServer(serverId);
    requireSpec(server);

    const kind = opts?.kind ?? "restart";
    const command = opts?.command ?? null;
    const intervalMinutes = opts?.intervalMinutes ?? null;

    // Validate based on schedule kind
    if (kind === "command") {
      if (!command) return { ok: false, error: "A command is required for command schedules." };
      if (!Object.keys(SCHEDULE_COMMANDS).includes(command))
        return { ok: false, error: `"${command}" is not an allowed scheduled command.` };
      if (intervalMinutes == null) return { ok: false, error: "An interval is required for command schedules." };
      if (!(ALLOWED_INTERVALS as readonly number[]).includes(intervalMinutes))
        return { ok: false, error: "Pick a valid interval." };
    } else {
      if (!validTime(hour, minute)) return { ok: false, error: "Pick a valid time (HH:MM, UTC)." };
    }

    const limited = throttle(user.id, "sched", 30);
    if (limited) return { ok: false, error: limited };
    const count = await db.gameSchedule.count({ where: { serverId } });
    if (count >= MAX_SCHEDULES) return { ok: false, error: `You can have at most ${MAX_SCHEDULES} schedules.` };

    const now = new Date();
    await db.gameSchedule.create({
      data: {
        serverId,
        kind,
        command,
        hour: kind === "command" ? 0 : Math.trunc(hour),
        minute: kind === "command" ? 0 : Math.trunc(minute),
        intervalMinutes,
        announce: kind === "restart" ? !!announce : false,
        enabled: true,
        nextRunAt: intervalMinutes
          ? computeNextInterval(intervalMinutes, now)
          : computeNextRun(Math.trunc(hour), Math.trunc(minute)),
      },
    });
    const detail = kind === "command"
      ? `cmd:${command} every ${intervalMinutes}min on ${server.hostname}`
      : `${hour}:${minute} on ${server.hostname}`;
    await db.auditLog.create({
      data: { userId: user.id, action: "gameserver.schedule.create", detail },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

async function ownedSchedule(id: string) {
  const user = await requireUser();
  const sched = await db.gameSchedule.findUnique({ where: { id }, include: { server: { select: { userId: true } } } });
  if (!sched) throw new Error("Not found");
  if (sched.server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, sched };
}

export async function updateGameSchedule(
  id: string,
  patch: { hour?: number; minute?: number; enabled?: boolean; announce?: boolean }
): Promise<Result> {
  try {
    const { user, sched } = await ownedSchedule(id);
    const hour = patch.hour ?? sched.hour;
    const minute = patch.minute ?? sched.minute;
    const enabled = patch.enabled ?? sched.enabled;

    // Interval-based schedules ignore hour/minute; daily schedules validate them.
    if (!sched.intervalMinutes && !validTime(hour, minute))
      return { ok: false, error: "Pick a valid time (HH:MM, UTC)." };

    let nextRunAt: Date | null = null;
    if (enabled) {
      nextRunAt = sched.intervalMinutes
        ? computeNextInterval(sched.intervalMinutes)
        : computeNextRun(Math.trunc(hour), Math.trunc(minute));
    }

    await db.gameSchedule.update({
      where: { id },
      data: {
        hour: sched.intervalMinutes ? sched.hour : Math.trunc(hour),
        minute: sched.intervalMinutes ? sched.minute : Math.trunc(minute),
        enabled,
        announce: patch.announce ?? sched.announce,
        nextRunAt,
      },
    });
    await db.auditLog.create({ data: { userId: user.id, action: "gameserver.schedule.update", detail: id } });
    revalidatePath(`/dashboard/servers/${sched.serverId}`);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function deleteGameSchedule(id: string): Promise<Result> {
  try {
    const { user, sched } = await ownedSchedule(id);
    await db.gameSchedule.delete({ where: { id } });
    await db.auditLog.create({ data: { userId: user.id, action: "gameserver.schedule.delete", detail: id } });
    revalidatePath(`/dashboard/servers/${sched.serverId}`);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

// ---------------------------------------------------------------------------
// Roles & Permissions (LuckPerms on paid Minecraft VMs)
// ---------------------------------------------------------------------------

import { createHash } from "node:crypto";
import { isGateableCommandNode, FREEMC_GATEABLE_COMMANDS } from "./freemc-command-catalog";

const ROLE_NAME_RE = /^[a-z][a-z0-9_]{2,19}$/;
const RESERVED_ROLE_NAMES = new Set(["default"]);

function offlineUuidFor(name: string): string {
  const hash = createHash("md5").update(`OfflinePlayer:${name}`, "utf8").digest();
  hash[6] = (hash[6] & 0x0f) | 0x30;
  hash[8] = (hash[8] & 0x3f) | 0x80;
  const hex = hash.toString("hex");
  return [hex.slice(0, 8), hex.slice(8, 12), hex.slice(12, 16), hex.slice(16, 20), hex.slice(20)].join("-");
}

type ParsedLpFile = { name: string | null; uuid: string | null; permissions: string[]; parents: string[] };

function parseLuckPermsFile(text: string): ParsedLpFile {
  const lines = text.split("\n").map((l) => l.replace(/\r$/, ""));
  let name: string | null = null;
  let uuid: string | null = null;
  const permissions: string[] = [];
  const parents: string[] = [];
  let section: "none" | "permissions" | "parents" = "none";
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line === "") continue;
    const isTopLevelKey = /^[A-Za-z-]+:/.test(line);
    if (isTopLevelKey) {
      if (/^name:/.test(line)) name = line.slice(5).trim().replace(/^'(.*)'$/, "$1");
      else if (/^uuid:/.test(line)) uuid = line.slice(5).trim();
      section = /^permissions:\s*$/.test(line) ? "permissions" : /^parents:\s*$/.test(line) ? "parents" : "none";
      continue;
    }
    const negatedHead = line.match(/^-\s+(\S+):\s*$/);
    const bare = line.match(/^-\s+(\S+)\s*$/);
    if (section === "permissions") {
      if (negatedHead) {
        const next = lines[i + 1] ?? "";
        const valMatch = next.match(/^\s+value:\s*(true|false)\s*$/);
        if (valMatch) i++;
        if (valMatch?.[1] === "true") permissions.push(negatedHead[1]);
      } else if (bare) {
        permissions.push(bare[1]);
      }
    } else if (section === "parents" && bare) {
      parents.push(bare[1]);
    }
  }
  return { name, uuid, permissions, parents };
}

async function readVmLpStorageDir(
  sshConn: Parameters<typeof exec>[0],
  dir: string,
): Promise<{ key: string; text: string }[]> {
  const MARK = "===GAME_ROLES_FILE:";
  const cmd =
    `d=${JSON.stringify(dir)}; [ -d "$d" ] || exit 0; for f in "$d"/*.yml; do [ -f "$f" ] || continue; ` +
    `echo "${MARK}$(basename "$f" .yml)==="; cat "$f"; done`;
  const r = await exec(sshConn, cmd, 15_000);
  if (r.code !== 0 || !r.stdout.trim()) return [];
  const out: { key: string; text: string }[] = [];
  const parts = r.stdout.split(new RegExp(`^${MARK}(.+?)===$`, "m"));
  for (let i = 1; i < parts.length; i += 2) {
    out.push({ key: parts[i], text: parts[i + 1] ?? "" });
  }
  return out;
}

async function findLpDir(sshConn: Parameters<typeof exec>[0], spec: GameControlSpec): Promise<string | null> {
  for (const root of spec.dataRoots) {
    const check = await exec(sshConn, `[ -d ${JSON.stringify(root + "/plugins/LuckPerms")} ] && echo ok`, 5_000);
    if (check.stdout.trim() === "ok") return `${root}/plugins/LuckPerms`;
  }
  return null;
}

export type GameRole = {
  name: string;
  permissions: string[];
  members: { uuid: string; name: string | null }[];
};

export async function detectGameLuckPerms(
  serverId: string
): Promise<{ ok: true; installed: boolean; hasYamlStorage: boolean } | { ok: false; error: string }> {
  try {
    const { user, server } = await ownedServer(serverId);
    const spec = requireSpec(server);
    if (spec.family !== "minecraft") return { ok: false, error: "Roles are only available for Minecraft." };
    const limited = throttle(user.id, "mc-mgmt", 30);
    if (limited) return { ok: false, error: limited };
    if (SANDBOX) return { ok: true, installed: true, hasYamlStorage: true };
    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running." };
    const res = await withServerSsh(server as SftpServer, async (conn) => {
      const pluginsRes = await runRcon(conn, spec, "plugins");
      if (!pluginsRes.ok) return { installed: false, hasYamlStorage: false };
      const installed = /luckperms/i.test(stripAnsi(pluginsRes.response));
      if (!installed) return { installed: false, hasYamlStorage: false };
      const lpDir = await findLpDir(conn, spec);
      if (!lpDir) return { installed: true, hasYamlStorage: false };
      const configRead = await exec(conn, `cat ${JSON.stringify(lpDir + "/config.yml")} 2>/dev/null`, 5_000);
      const hasYaml = /^storage-method:\s*yaml\s*$/m.test(configRead.stdout);
      return { installed: true, hasYamlStorage: hasYaml };
    });

    });
    return { ok: true, ...res };
  } catch (err) { return { ok: false, error: safeError(err) }; }
}

export async function ensureGameLpYamlStorage(
  serverId: string
): Promise<Result> {
  try {
    const { user, server } = await ownedServer(serverId);
    const spec = requireSpec(server);
    if (spec.family !== "minecraft") return { ok: false, error: "Roles are only available for Minecraft." };
    if (SANDBOX) return { ok: true };
    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running." };
    const res = await withServerSsh(server as SftpServer, async (conn) => {
      const lpDir = await findLpDir(conn, spec);
      if (!lpDir) return { ok: false as const, error: "LuckPerms not found. Install it from the Plugins tab first." };
      const configPath = `${lpDir}/config.yml`;
      const configRead = await exec(conn, `cat ${JSON.stringify(configPath)}`, 5_000);
      if (configRead.code !== 0) return { ok: false as const, error: "Can't read LuckPerms config." };
      const hasYaml = /^storage-method:\s*yaml\s*$/m.test(configRead.stdout);
      const hasUuidCache = /^use-server-uuid-cache:\s*true\s*$/m.test(configRead.stdout);
      if (hasYaml && hasUuidCache) return { ok: true as const };
      await exec(conn, `sed -i -e 's/^storage-method:.*/storage-method: yaml/' -e 's/^use-server-uuid-cache:.*/use-server-uuid-cache: true/' ${JSON.stringify(configPath)}`, 5_000);
      const rcon = await runRcon(conn, spec, "lp reload");
      if (!rcon.ok) return { ok: false as const, error: "Couldn't reload LuckPerms — try restarting your server." };
      return { ok: true as const };
    });
    return res;
  } catch (err) { return { ok: false, error: safeError(err) }; }
}

export async function listGameRoles(
  serverId: string
): Promise<{ ok: true; roles: GameRole[] } | { ok: false; error: string }> {
  try {
    const { user, server } = await ownedServer(serverId);
    const spec = requireSpec(server);
    if (spec.family !== "minecraft") return { ok: false, error: "Roles are only available for Minecraft." };
    const limited = throttle(user.id, "mc-mgmt", 30);
    if (limited) return { ok: false, error: limited };
    if (SANDBOX) return { ok: true, roles: [{ name: "vip", permissions: ["essentials.fly", "essentials.heal"], members: [{ uuid: "test", name: "Steve" }] }] };
    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running." };
    const roles = await withServerSsh(server as SftpServer, async (conn) => {
      const lpDir = await findLpDir(conn, spec);
      if (!lpDir) return [];
      const groupsDir = `${lpDir}/yaml-storage/groups`;
      const usersDir = `${lpDir}/yaml-storage/users`;
      const [groupFiles, userFiles] = await Promise.all([
        readVmLpStorageDir(conn, groupsDir),
        readVmLpStorageDir(conn, usersDir),
      ]);
      const users = userFiles.map(({ key, text }) => ({ ...parseLuckPermsFile(text), uuid: key }));
      return groupFiles
        .filter(({ key }) => !RESERVED_ROLE_NAMES.has(key))
        .map(({ key, text }) => {
          const parsed = parseLuckPermsFile(text);
          const members = users
            .filter((u) => u.parents.includes(key))
            .map((u) => ({ uuid: u.uuid, name: u.name && u.name !== "null" ? u.name : null }));
          return { name: key, permissions: parsed.permissions.filter(isGateableCommandNode), members };
        });
    });
    return { ok: true, roles };
  } catch (err) { return { ok: false, error: safeError(err) }; }
}

export async function createGameRole(serverId: string, roleName: string): Promise<Result> {
  try {
    const name = roleName.trim().toLowerCase();
    if (!ROLE_NAME_RE.test(name) || RESERVED_ROLE_NAMES.has(name))
      return { ok: false, error: "Role names: 3-20 lowercase letters, numbers, or underscores, starting with a letter." };
    const r = await mcRcon(serverId, `lp creategroup ${name}`, "gameserver.role.create", name);
    return r.ok ? { ok: true } : r;
  } catch (err) { return { ok: false, error: safeError(err) }; }
}

export async function deleteGameRole(serverId: string, roleName: string): Promise<Result> {
  try {
    const name = roleName.trim().toLowerCase();
    if (!ROLE_NAME_RE.test(name) || RESERVED_ROLE_NAMES.has(name)) return { ok: false, error: "Unknown role." };
    const r = await mcRcon(serverId, `lp deletegroup ${name}`, "gameserver.role.delete", name);
    return r.ok ? { ok: true } : r;
