}

export async function setGameRolePermission(serverId: string, roleName: string, node: string, enabled: boolean): Promise<Result> {
  try {
    const name = roleName.trim().toLowerCase();
    if (!ROLE_NAME_RE.test(name) || RESERVED_ROLE_NAMES.has(name)) return { ok: false, error: "Unknown role." };
    if (!isGateableCommandNode(node)) return { ok: false, error: "Unsupported command." };
    const verb = enabled ? "permission set" : "permission unset";
