export type PlayerSessionRow = {
  id: string;
  playerName: string;
  joinedAt: string;
  leftAt: string | null;
  durationMs: number | null;
};

export type PlayerHistoryResult =
  | { ok: true; sessions: PlayerSessionRow[]; total: number }
  | { ok: false; error: string };

export async function getPlayerHistory(
  serverId: string,
  opts?: { limit?: number; offset?: number; playerName?: string }
): Promise<PlayerHistoryResult> {
  try {
    const { server } = await ownedServer(serverId);
    const limit = Math.min(opts?.limit ?? 100, 200);
    const offset = opts?.offset ?? 0;
    const where: any = { serverId: server.id };
    if (opts?.playerName) {
      where.playerName = { contains: opts.playerName, mode: "insensitive" };
    }

    const [sessions, total] = await Promise.all([
      db.playerSession.findMany({
        where,
        orderBy: { joinedAt: "desc" },
        take: limit,
        skip: offset,
      }),
      db.playerSession.count({ where }),
    ]);

    return {
      ok: true,
      total,
      sessions: sessions.map((s) => ({
        id: s.id,
        playerName: s.playerName,
        joinedAt: s.joinedAt.toISOString(),
        leftAt: s.leftAt?.toISOString() ?? null,
        durationMs: s.leftAt
          ? s.leftAt.getTime() - s.joinedAt.getTime()
          : null,
      })),
    };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export type PlayerStatsResult =
  | {
      ok: true;
      uniquePlayers: number;
      totalPlaytimeMs: number;
      avgSessionMs: number;
      currentOnline: number;
      topPlayers: { name: string; totalMs: number; sessions: number }[];
    }
  | { ok: false; error: string };

export async function getPlayerStats(serverId: string): Promise<PlayerStatsResult> {
  try {
    const { server } = await ownedServer(serverId);

    const [allSessions, currentOnline] = await Promise.all([
      db.playerSession.findMany({
        where: { serverId: server.id },
        select: { playerName: true, joinedAt: true, leftAt: true },
      }),
      db.playerSession.count({
        where: { serverId: server.id, leftAt: null },
      }),
    ]);

    const playerMap = new Map<string, { totalMs: number; sessions: number }>();
    let totalPlaytimeMs = 0;
    let completedSessions = 0;

    for (const s of allSessions) {
      const ms = s.leftAt
        ? s.leftAt.getTime() - s.joinedAt.getTime()
        : Date.now() - s.joinedAt.getTime();
      totalPlaytimeMs += ms;
      if (s.leftAt) completedSessions++;

      const key = s.playerName.toLowerCase();
      const existing = playerMap.get(key) ?? { totalMs: 0, sessions: 0 };
      existing.totalMs += ms;
      existing.sessions += 1;
      playerMap.set(key, existing);
    }

    // Preserve original casing for display: use the first-seen casing
    const nameCasing = new Map<string, string>();
    for (const s of allSessions) {
      const key = s.playerName.toLowerCase();
      if (!nameCasing.has(key)) nameCasing.set(key, s.playerName);
    }

    const topPlayers = [...playerMap.entries()]
      .sort((a, b) => b[1].totalMs - a[1].totalMs)
      .slice(0, 10)
      .map(([key, data]) => ({
        name: nameCasing.get(key) ?? key,
        totalMs: data.totalMs,
        sessions: data.sessions,
      }));

    return {
      ok: true,
      uniquePlayers: playerMap.size,
      totalPlaytimeMs,
      avgSessionMs: completedSessions > 0 ? Math.round(totalPlaytimeMs / allSessions.length) : 0,
      currentOnline,
      topPlayers,
    };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

