import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import type { SftpServer } from "../lib/sftp";
import { withServerSsh, exec, SETUP_TIMEOUT_MS } from "../lib/ssh-exec";
import {
  controlSpec,
  isGameFamily,
  isPowerAction,
  remoteLocateDir,
  runRcon,
  parsePlayers,
  computeNextRun,
  computeNextIntervalRun,
  shq,
  isSafeRemotePath,
  GAME_BACKUP_DIR,
  type GameControlSpec,
} from "../lib/game-control";
import type { Job } from "@prisma/client";

/**
 * Game server control-panel worker handlers.
 *
 * Registered in worker/index.ts:
 *   GAME_POWER:  gamePower,
 *   GAME_BACKUP: gameBackup,
 * and `gameScheduleSweep()` called on a ~60s timer.
 *
 * Everything runs over the platform's existing SSH (lib/ssh-exec withServerSsh —
 * host/port/root-password derived exactly like lib/sftp). Family/unit/path values
 * that reach the shell are compile-time constants or allowlisted (lib/game-control),
 * and the root password is never surfaced in an error (only a trimmed remote stderr
 * is, which never contains it).
 *
 * SANDBOX / no VM: handlers notify a simulation and touch nothing.
 */

const CONTROL_FIELDS = {
  id: true,
  userId: true,
  hostname: true,
  status: true,
  rootPassword: true,
  rootPasswordEnc: true,
  sshPort: true,
  dedicatedIp: { select: { address: true } },
  osTemplate: { select: { family: true } },
  gamePlan: { select: { gameFamily: true } },
} as const;

type ControlServer = {
  id: string;
  userId: string;
  hostname: string;
  status: string;
  rootPassword: string | null;
  rootPasswordEnc: string | null;
  sshPort: number | null;
  dedicatedIp: { address: string } | null;
  osTemplate: { family: string | null };
  gamePlan: { gameFamily: string | null } | null;
};

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[game-control] notify failed", e);
  }
}

function resolveSpec(server: ControlServer): GameControlSpec {
  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
  if (!isGameFamily(fam)) throw new Error("not a game server");
  const spec = controlSpec(fam);
  if (!spec) throw new Error("no control spec for family");
  return spec;
}

/**
 * Build the remote unit-resolution + systemctl script. `hints`/`family` come from
 * the family's control spec (compile-time constants); `action` is one of the three
 * allowlisted verbs. Emits NXGP markers so a clean SSH exit is never mistaken for
 * a successful action (the same discipline as worker/game-update.ts).
 */
function powerScript(spec: GameControlSpec, action: string): string {
  const hints = spec.serviceHints.map(shq).join(" ");
  return [
    `unit=""`,
    `for c in ${hints}; do systemctl cat "$c" >/dev/null 2>&1 && { unit="$c"; break; }; done`,
    `if [ -z "$unit" ]; then unit=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${shq(spec.family)} | head -1 | awk '{print $1}'); fi`,
    `if [ -z "$unit" ]; then echo "NXGP:UNIT:NONE"; exit 0; fi`,
    `echo "NXGP:UNIT:$unit"`,
    `systemctl ${action} "$unit" >/dev/null 2>&1; echo "NXGP:RC:$?"`,
    `st=$(systemctl is-active "$unit" 2>/dev/null); echo "NXGP:STATE:${"$"}{st:-unknown}"`,
    `echo "NXGP:END"`,
  ].join("\n");
}

/** GAME_POWER — start/stop/restart the game SERVICE (not the VM). */
export async function gamePower(job: Job): Promise<void> {
  if (!job.serverId) throw new Error("game power: missing serverId");
  const server = (await db.server.findUnique({ where: { id: job.serverId }, select: CONTROL_FIELDS })) as ControlServer | null;
  if (!server) throw new Error(`Server ${job.serverId} not found`);
  const spec = resolveSpec(server);

  const p = (job.payload ?? {}) as { action?: string; announce?: boolean };
  const action = String(p.action ?? "");
  if (!isPowerAction(action)) throw new Error(`unsupported power action: ${action}`);
  const href = `/dashboard/servers/${server.id}?tab=manage`;

  if (SANDBOX) {
    await notify(
      server.userId,
      `Game service ${action} (sandbox) on ${server.hostname}`,
      `Sandbox only — no VM was contacted; the ${spec.label} service was not ${action}ed.`,
      href
    );
    return;
  }
  if (server.status !== "RUNNING") throw new Error("game power: VM is not running");

  // Optional pre-restart announce over RCON (best-effort; never fails the action).
  if (action === "restart" && p.announce && spec.rcon === "source") {
    try {
      await withServerSsh(server as SftpServer, (conn) =>
        runRcon(conn, spec, "say Server is restarting now (scheduled/maintenance).")
      );
    } catch (e) {
      console.error("[game-control] restart announce failed (continuing)", e);
    }
  }

  const out = await withServerSsh(server as SftpServer, (conn) => exec(conn, powerScript(spec, action), SETUP_TIMEOUT_MS));
  const text = out.stdout;
  if (/NXGP:UNIT:NONE/.test(text)) {
    await notify(server.userId, `Could not ${action} the ${spec.label} service`, `No game service unit was found on ${server.hostname}.`, href);
    throw new Error("game power: no service unit found");
  }
  const rc = Number(/NXGP:RC:(-?\d+)/.exec(text)?.[1] ?? "1");
  const state = /NXGP:STATE:(\w+)/.exec(text)?.[1] ?? "unknown";
  if (!/NXGP:END/.test(text) || rc !== 0) {
    await notify(server.userId, `Could not ${action} the ${spec.label} service`, `The ${action} did not complete on ${server.hostname} (state: ${state}).`, href);
    throw new Error(`game power: ${action} failed rc=${rc} state=${state}`);
  }
  await notify(
    server.userId,
    `${spec.label} service ${action}ed on ${server.hostname}`,
    action === "stop" ? "The game service was stopped." : `The game service was ${action}ed (now ${state}).`,
    href
  );
}

/** GAME_BACKUP — archive the world/save dir into a downloadable .tar.gz. */
export async function gameBackup(job: Job): Promise<void> {
  if (!job.serverId) throw new Error("game backup: missing serverId");
  const server = (await db.server.findUnique({ where: { id: job.serverId }, select: CONTROL_FIELDS })) as ControlServer | null;
  if (!server) throw new Error(`Server ${job.serverId} not found`);
  const spec = resolveSpec(server);
  const href = `/dashboard/servers/${server.id}?tab=manage`;

  if (SANDBOX) {
    await notify(server.userId, `World backup created (sandbox) on ${server.hostname}`, `Sandbox only — no VM was contacted for the ${spec.label} world backup.`, href);
    return;
  }
  if (server.status !== "RUNNING") throw new Error("game backup: VM is not running");

  const outcome = await withServerSsh(server as SftpServer, async (conn) => {
    const dir = await remoteLocateDir(conn, spec.dataRoots);
    if (!dir || !isSafeRemotePath(dir)) return { ok: false, msg: "Could not locate the world/save directory." };
    // Timestamped archive under the fixed backup dir. `parent`/`base` are derived
    // from the located (allowlisted) dir; every value interpolated is single-quoted.
    const ts = new Date().toISOString().replace(/[-:]/g, "").replace(/\..+$/, "").replace("T", "-");
    const archive = `${GAME_BACKUP_DIR}/${spec.family}-${ts}.tar.gz`;
    const parent = dir.replace(/\/[^/]+$/, "") || "/";
    const base = dir.replace(/^.*\//, "");
    const script =
      `mkdir -p ${shq(GAME_BACKUP_DIR)} && ` +
      `tar czf ${shq(archive)} -C ${shq(parent)} ${shq(base)} 2>&1 && ` +
      `stat -c '%s' ${shq(archive)}`;
    const r = await exec(conn, script, SETUP_TIMEOUT_MS);
    if (r.code !== 0) return { ok: false, msg: (r.stderr || r.stdout).trim().slice(0, 200) || "tar failed" };
    const size = Number(r.stdout.trim().split(/\r?\n/).pop());
    return { ok: true, archive, size: Number.isFinite(size) ? size : 0 };
  });

  if (!outcome.ok) {
    await notify(server.userId, `World backup failed on ${server.hostname}`, outcome.msg, href);
    throw new Error(`game backup failed: ${outcome.msg}`);
  }
  const mb = ((outcome.size ?? 0) / (1024 * 1024)).toFixed(1);
  await notify(
    server.userId,
    `${spec.label} world backup ready on ${server.hostname}`,
    `Backed up your world (${mb} MB). Download it from the Manage → Worlds tab.`,
    href
  );
}

/**
 * Fire due scheduled tasks. Selects enabled GameSchedule rows whose `nextRunAt`
 * has passed. For kind="restart", enqueues a GAME_POWER restart; for kind="command",
 * sends an RCON command directly. Advances `nextRunAt` appropriately (daily or
 * interval-based). Idempotent / safe on a timer.
 */
export async function gameScheduleSweep(): Promise<void> {
  const now = new Date();
  const due = await db.gameSchedule.findMany({
    where: { enabled: true, nextRunAt: { lte: now } },
    include: { server: { select: { id: true, status: true, osTemplate: { select: { family: true } }, gamePlan: { select: { gameFamily: true } } } } },
    take: 100,
  });
  if (due.length === 0) return;

  for (const s of due) {
    // Always advance the clock first so a server that is down / mid-operation does
    // not cause the same row to be reselected every tick.
    const nextRunAt = s.intervalMinutes
      ? computeNextIntervalRun(s.intervalMinutes, now)
      : computeNextRun(s.hour, s.minute, now);
    await db.gameSchedule.update({ where: { id: s.id }, data: { lastRunAt: now, nextRunAt } }).catch(() => {});

    const fam = s.server.gamePlan?.gameFamily ?? s.server.osTemplate?.family ?? null;
    if (!isGameFamily(fam)) continue;
    if (s.server.status !== "RUNNING") continue;

    if (s.kind === "command" && s.command) {
      // Send RCON command directly (e.g. save-all, weather clear).
      const spec = controlSpec(fam);
      if (!spec || spec.rcon === "none") continue;
      // Load full server for SSH access.
      const server = await db.server.findUnique({ where: { id: s.server.id }, select: CONTROL_FIELDS });
      if (!server) continue;
      try {
        await withServerSsh(server as SftpServer, (conn) => runRcon(conn, spec, s.command!));
      } catch {
        // Best-effort: command schedules silently skip on failure.
      }
    } else {
      // Restart schedule: check for busy jobs first.
      const busy = await db.job.count({
        where: {
          serverId: s.server.id,
          status: { in: ["QUEUED", "RUNNING"] },
          type: { in: ["GAME_POWER", "GAME_BACKUP", "PROVISION", "REINSTALL", "DELETE", "RESIZE", "BACKUP_RESTORE"] as any },
        },
      });
      if (busy > 0) continue;

      await db.job.create({ data: { type: "GAME_POWER", serverId: s.server.id, payload: { action: "restart", announce: s.announce } } });
    }
  }
}

/**
 * Track player join/leave events by comparing the live RCON player list against
 * open PlayerSession rows (leftAt IS NULL). Runs every ~60s from the main loop.
 *
 * For each RUNNING game server with a gamePlan:
 *   - NEW players (in RCON but no open session) → create a PlayerSession
 *   - DEPARTED players (open session but not in RCON) → set leftAt = now()
 *   - STILL ONLINE → no-op
 *
 * Per-server try/catch so one unreachable VM never blocks the sweep.
 */
export async function playerTrackingSweep(): Promise<void> {
  if (SANDBOX) return;

  const servers = await db.server.findMany({
    where: { status: "RUNNING", gamePlanId: { not: null } },
    select: CONTROL_FIELDS,
  });

  const now = new Date();

  for (const server of servers) {
    try {
      const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
      if (!isGameFamily(fam)) continue;
      const spec = controlSpec(fam);
      if (!spec || spec.rcon !== "source" || !spec.listCommand) continue;

      // Get online players via RCON
      const res = await withServerSsh(server as SftpServer, (conn) =>
        runRcon(conn, spec, spec.listCommand!)
      );
      if (!res.ok) continue;
      const { players: onlinePlayers } = parsePlayers(spec.family, res.response);
      const onlineNames = new Set(onlinePlayers.map((p) => p.name.toLowerCase()));

      // Get open sessions for this server
      const openSessions = await db.playerSession.findMany({
        where: { serverId: server.id, leftAt: null },
      });
      const sessionByName = new Map(
        openSessions.map((s) => [s.playerName.toLowerCase(), s])
      );

      // NEW players: in RCON but no open session
      for (const p of onlinePlayers) {
        if (!sessionByName.has(p.name.toLowerCase())) {
          await db.playerSession.create({
            data: { serverId: server.id, playerName: p.name },
          });
        }
      }

      // DEPARTED players: open session but not in RCON
      for (const session of openSessions) {
        if (!onlineNames.has(session.playerName.toLowerCase())) {
          await db.playerSession.update({
            where: { id: session.id },
            data: { leftAt: now },
          });
        }
      }
    } catch (e) {
      // Per-server: one failure must not break the sweep
      console.error(`[player-tracking] sweep failed for server ${server.id}`, e);
    }
  }
}

