 *  research summary in the dashboard build: difficulty and whitelist on/off
 *  have real vanilla commands; gamemode's live command only affects players
 *  currently online (not new joiners), so it's listed as restart-only here to
 *  avoid a UI that claims "applied" while a reconnecting player gets the old
 *  value. MOTD and max-players have no vanilla live command at all. */
export function liveRconCommandFor(key: string, value: string): string | null {
