export const FREEMC_GAME_TYPES: Record<string, FreeMcGameType> = Object.fromEntries(
  GAME_TYPE_KEYS.map((key) => [key, buildGameType(key)]),
) as Record<string, FreeMcGameType>;

export type FreeMcGameMode = {
