};

export const FREEMC_GAME_MODES: Record<string, FreeMcGameMode> = {
  survival: {
    label: "Survival",
    description: "The default experience — normal difficulty, mobs and hunger on.",
    properties: { gamemode: "survival", hardcore: "false", difficulty: "normal" },
  },
  hardcore: {
