/**
 * Patches EssentialsX's `custom-join-message` (config.yml) in place with a
 * given message — read-modify-write over the whole file rather than a `sed`
 * one-liner (unlike the IridiumSkyblock patch below) because the message
 * itself is full of `&` colour codes, which `sed`'s replacement syntax treats
 * as "insert the matched text" unless individually escaped — a real footgun
 * for a value built from data, not a fixed literal. Read+regex+writeback (via
 * execInput's stdin path, same mechanism as writeServerProperties) sidesteps
 * that whole class of shell/sed escaping bug entirely. Live-verified this
 * session: a config patched this way survives an immediate `docker restart`
 * (the same restart applyModeProperties always does right after this runs)
 * with no YAML parse errors and Essentials fully re-enabling.
 */
async function patchEssentialsJoinMessage(
  conn: Client,
  containerName: string,
  message: string,
): Promise<{ ok: boolean; error?: string }> {
  const path = "/data/plugins/Essentials/config.yml";
  const read = await dockerExec(conn, containerName, `cat ${path}`, 10_000);
  if (read.code !== 0) {
    return { ok: false, error: read.stderr.trim() || "Could not read Essentials config.yml" };
  }
  // YAML double-quoted scalar: only \ and " need escaping (our messages never
  // contain either today, but a future edit might).
  const yamlValue = message.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
  const patched = read.stdout.replace(/^custom-join-message:.*$/m, `custom-join-message: "${yamlValue}"`);

export async function startFreeMinecraftServer(_prev: unknown, _formData: FormData): Promise<Result> {
  return powerAction("start");
}
export async function stopFreeMinecraftServer(_prev: unknown, _formData: FormData): Promise<Result> {
  return powerAction("stop");
}
export async function restartFreeMinecraftServer(_prev: unknown, _formData: FormData): Promise<Result> {
  return powerAction("restart");
}

async function powerAction(action: "start" | "stop" | "restart"): Promise<Result> {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return { error: "You don't have a free server." };

  const rl = checkRateLimit(`freemc:power:${user.id}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };

  try {
    const host = await freemcHost();
    const outcome = await withServerSsh(host, async (conn) => {
      // "start" always wakes a currently-stopped container, and "restart" on
      // one that's ALREADY stopped does too (docker's restart just starts it)
      // — either way that's a customer explicitly turning a container from
      // stopped into running, the exact path lib/freemc-capacity.ts's module
      // doc says this app controls and should gate (unlike mc-router's own
      // passive wake, which happens outside this app entirely). A restart of
      // an already-running container doesn't change what's committed, so it's
      // deliberately left ungated — same reasoning applies to "stop", which
      // only ever frees capacity.
      if (action !== "stop") {
        const running = await exec(
          conn,
          `docker inspect -f '{{.State.Running}}' ${shellQuote(row.containerName)}`,
          10_000,
        );
        const isRunning = running.code === 0 && running.stdout.trim() === "true";
        if (!isRunning) {
          const assigned = await exec(
            conn,
            `docker inspect ${shellQuote(row.containerName)} --format '{{.HostConfig.NanoCpus}} {{.HostConfig.Memory}}'`,
            10_000,
          );
          if (assigned.code === 0) {
            const [nanoCpusRaw, memBytesRaw] = assigned.stdout.trim().split(/\s+/);
            const cpus = (Number.parseInt(nanoCpusRaw, 10) || 0) / 1e9;
            const ramMb = Math.round((Number.parseInt(memBytesRaw, 10) || 0) / (1024 * 1024));
            const capacity = await getFreemcHostCapacity(conn);
            const capCheck = wouldExceedFreemcCapacity(capacity, cpus, ramMb);
            if (capCheck.exceeds) {
              return { ok: false as const, error: "Free servers are at capacity right now — try again in a few minutes." };
            }
          }
          // If the inspect itself failed (container missing entirely), fall
          // through and let the docker action below produce the real error —
          // no point capacity-gating a container that doesn't exist.
        }
      }
      const r = await exec(conn, `docker ${action} ${shellQuote(row.containerName)}`, 30_000);
      if (r.code !== 0) return { ok: false as const, error: r.stderr || `docker ${action} failed` };
      return { ok: true as const };
    });
    if (!outcome.ok) return { error: outcome.error };
  } catch (e) {
    console.error(`[free-minecraft] ${action} failed:`, e);
    return { error: "That didn't work — please try again in a moment." };
  }
  revalidatePath("/dashboard/free-minecraft");
  return {};
}

export async function renameFreeMinecraftServer(_prev: unknown, formData: FormData): Promise<Result> {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return { error: "You don't have a free server." };

  const name = String(formData.get("name") ?? "").trim().slice(0, 40);
  if (!name) return { error: "Enter a name." };

  // Cosmetic only — never touches the container, the subdomain, or mc-router.
  await db.freeMinecraftServer.update({ where: { id: row.id }, data: { name } });
  revalidatePath("/dashboard/free-minecraft");
  return {};
}

/**
 * Changes the connect address. The container's own identity (containerName,
 * data volume) never changes — only its `mc-router.host` label does, and
 * labels are immutable on a running container, so this is a stop -> remove ->
 * recreate with the SAME name and data mount, just a new label. World data is
 * untouched throughout; there's a few seconds of downtime while it recreates.
 */
export async function changeFreeMinecraftSubdomain(_prev: unknown, formData: FormData): Promise<Result> {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return { error: "You don't have a free server." };

  const rl = checkRateLimit(`freemc:subdomain:${user.id}`, { max: 5, windowMs: 300_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${Math.ceil(rl.retryAfterSec / 60)}m.` };

  const sub = String(formData.get("subdomain") ?? "").trim().toLowerCase();
  const subdomainError = validateSubdomainFormat(sub);
  if (subdomainError) return { error: subdomainError };
  if (sub === row.subdomain) return {};
  if (!(await isSubdomainAvailable(sub, { excludeFreeMcId: row.id }))) return { error: "That name is taken — try another." };

  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
  const ramMb = await getSettingInt("free_minecraft_ram_mb", 1024);
  // Preserve whatever game type/mode was active — moving your connect
  // address shouldn't reset your world or plugins.
  const gameTypeKey = FREEMC_GAME_TYPES[row.activeGameType] ? row.activeGameType : "vanilla";
  const gameType = FREEMC_GAME_TYPES[gameTypeKey];
  const gameMode = FREEMC_GAME_MODES[row.activeGameMode] ?? FREEMC_GAME_MODES.survival;

  try {
    await db.freeMinecraftServer.update({ where: { id: row.id }, data: { subdomain: sub } });
  } catch {
    return { error: "That name is taken — try another." };
  }

  try {
    const host = await freemcHost();
    // "moved": now running under the new subdomain. "reverted": the new
    // address failed to boot, so it's back under the OLD one — the DB's
    // subdomain field must match, or the dashboard would show a "connect at"
    // address nothing is actually listening on.
    const outcome = await withServerSsh(host, async (conn) => {
      const applied = await recreateGameTypeContainer(conn, {
        containerName: row.containerName,
        dataPath: `/opt/freemc/servers/${row.id}`,
        subdomain: sub,
        domain,
        ramMb,
        ownerId: user.id,
        gameType,
        gameTypeKey,
        gameMode,
      });
      if (applied.ok) return { landed: "moved" as const };
      console.error("[free-minecraft] subdomain recreate failed, rolling back:", applied.error);
      const rolledBack = await recreateGameTypeContainer(conn, {
        containerName: row.containerName,
        dataPath: `/opt/freemc/servers/${row.id}`,
        subdomain: row.subdomain,
        domain,
        ramMb,
        ownerId: user.id,
        gameType,
        gameTypeKey,
        gameMode,
      });
      return rolledBack.ok
        ? { landed: "reverted" as const }
        : { landed: "broken" as const, error: rolledBack.error };
    });

    if (outcome.landed !== "moved") {
      await db.freeMinecraftServer.update({ where: { id: row.id }, data: { subdomain: row.subdomain } }).catch(() => {});
    }
    if (outcome.landed === "broken") throw new Error(outcome.error);
    if (outcome.landed === "reverted") {
      return { error: "That address didn't work — your server is back on its previous one." };
    }
  } catch (e) {
    console.error("[free-minecraft] subdomain change failed:", e);
    return { error: "Couldn't move your server to the new address — please try again." };
  }
  revalidatePath("/dashboard/free-minecraft");
  return {};
}

export async function sendFreeMinecraftCommand(_prev: unknown, formData: FormData): Promise<{ error?: string; response?: string }> {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return { error: "You don't have a free server." };

  const rl = checkRateLimit(`freemc:rcon:${user.id}`, { max: 20, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many commands — try again in ${rl.retryAfterSec}s.` };

  const parsed = validateRconCommand(String(formData.get("command") ?? ""));
  if (!parsed.ok) return { error: parsed.error };

  try {
    const host = await freemcHost();
    const result = await withServerSsh(host, (conn) => sendRcon(conn, row.containerName, user.id, parsed.command));
    if (!result.ok) return { error: result.error || "Server is asleep — connect first to wake it up." };
    return { response: result.response };
  } catch (e) {
    console.error("[free-minecraft] rcon command failed:", e);
    return { error: "Couldn't reach your server — is it asleep? Connect first to wake it up." };
  }
}

