/** Current server.properties values, shaped for the shared MINECRAFT schema
 *  (lib/game-config.ts) — same field defs/types/options the paid game panel's
 *  Settings tab uses, just applied through Docker instead of a VM job. */
export async function getFreeMinecraftSettings() {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return null;

  const schema = schemaFor("minecraft");
  if (!schema) return null;

  try {
    const host = await freemcHost();
    const properties = await withServerSsh(host, (conn) => readServerProperties(conn, row.containerName));
    return { schema, properties };
