export async function applyFreeMinecraftSettings(_prev: unknown, formData: FormData): Promise<Result> {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return { error: "You don't have a free server." };

  const schema = schemaFor("minecraft");
  if (!schema) return { error: "Settings aren't available." };

  const raw: Record<string, unknown> = {};
  for (const field of schema.fields) {
    const v = formData.get(field.key);
    if (v === null) continue;
    raw[field.key] = field.type === "bool" ? v === "true" : v;
  }
  const validated = validateConfig("minecraft", raw);
  if (!validated.ok) return { error: validated.error };

  const properties: Record<string, string> = {};
  for (const [k, v] of Object.entries(validated.values)) properties[k] = String(v);

  try {
    const host = await freemcHost();
    await withServerSsh(host, async (conn) => {
      // Push live-appliable keys immediately via RCON (instant effect for
      // anyone already connected), THEN write server.properties + restart so
      // the change also survives the restart and applies to everyone else —
      // see liveRconCommandFor's own note on which keys have a real live path.
      for (const [k, v] of Object.entries(properties)) {
        const liveCmd = liveRconCommandFor(k, v);
        if (liveCmd) await sendRcon(conn, row.containerName, user.id, liveCmd).catch(() => {});
      }
      const write = await writeServerProperties(conn, row.containerName, properties);
      if (!write.ok) throw new Error(write.error || "Could not write settings.");
      await exec(conn, `docker restart ${shellQuote(row.containerName)}`, 30_000);
    });
  } catch (e) {
    console.error("[free-minecraft] settings apply failed:", e);
    return { error: "Couldn't apply settings — please try again." };
  }
  await db.freeMinecraftServer.update({ where: { id: row.id }, data: { preset: "custom" } });
  revalidatePath("/dashboard/free-minecraft");
  return {};
}

/**
 * DEPRECATED entry point — kept only because the not-yet-migrated dashboard
 * UI (components/customer/freemc/FreeMcDashboard.tsx, off-limits to this
 * change) still binds its "Quick-start presets" cards to this exact action.
 * New code should call switchFreeMinecraftGameType / applyFreeMinecraftGameMode
 * in lib/actions-freemc-worlds.ts instead — this now just translates the old
 * flat key (mapLegacyPresetKey) and delegates to the same two-axis machinery
 * those use, so both entry points stay behaviorally identical and a world
 * switched from either one is isolated exactly the same way.
 */
export async function applyFreeMinecraftPreset(_prev: unknown, formData: FormData): Promise<Result> {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return { error: "You don't have a free server." };

  const presetKey = String(formData.get("preset") ?? "");
  const mapped = mapLegacyPresetKey(presetKey);
  if (!mapped) return { error: "Unknown preset." };
  const { gameType, gameMode } = mapped;
  const gameTypeDef = FREEMC_GAME_TYPES[gameType];
  const gameModeDef = FREEMC_GAME_MODES[gameMode];

  const rl = checkRateLimit(`freemc:preset:${user.id}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };

  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
  const ramMb = await getSettingInt("free_minecraft_ram_mb", 1024);

  try {
    const host = await freemcHost();

    if (gameType === row.activeGameType) {
      // Same world, only the mode differs (or this is a literal re-click of
      // the already-active card) — apply via RCON + a restart of the SAME
      // container, never a recreate, same discipline as
      // applyFreeMinecraftGameMode in lib/actions-freemc-worlds.ts.
      await withServerSsh(host, async (conn) => {
        const applied = await applyModeProperties(conn, row.containerName, user.id, gameModeDef);
        if (!applied.ok) throw new Error(applied.error || "Could not apply game mode.");
      });
    } else {
      // Different world entirely — full recreate with the SAME rollback
      // discipline the old flat-preset code used (see the retired
      // recreatePresetContainer's history: NEVER just restart here, a plugin
      // set baked into env vars survives a restart and silently keeps
      // running under the "old" preset otherwise). recreateGameTypeContainer
      // additionally sets `-e LEVEL=<gameType>`, so this world is isolated
      // from whatever the account had running before — this is the actual
      // production-incident fix.
      const previousTypeKey = FREEMC_GAME_TYPES[row.activeGameType] ? row.activeGameType : "vanilla";
      const previousTypeDef = FREEMC_GAME_TYPES[previousTypeKey];
      const previousModeDef = FREEMC_GAME_MODES[row.activeGameMode] ?? FREEMC_GAME_MODES.survival;

      const outcome = await withServerSsh(host, async (conn) => {
        await exec(conn, `docker exec ${shellQuote(row.containerName)} sh -c 'rm -rf /data/plugins/*'`, 15_000).catch(() => {});
        const applied = await recreateGameTypeContainer(conn, {
          containerName: row.containerName,
          dataPath: `/opt/freemc/servers/${row.id}`,
          subdomain: row.subdomain,
          domain,
          ramMb,
          ownerId: user.id,
          gameType: gameTypeDef,
          gameTypeKey: gameType,
          gameMode: gameModeDef,
        });
        if (applied.ok) return { ok: true as const };

        console.error("[free-minecraft] preset boot failed, rolling back:", applied.error);
        const rolledBack = await recreateGameTypeContainer(conn, {
          containerName: row.containerName,
          dataPath: `/opt/freemc/servers/${row.id}`,
          subdomain: row.subdomain,
          domain,
          ramMb,
          ownerId: user.id,
          gameType: previousTypeDef,
          gameTypeKey: previousTypeKey,
          gameMode: previousModeDef,
        });
        return rolledBack.ok
          ? { ok: false as const, error: "That preset didn't start cleanly, so we put your server back the way it was." }
          : { ok: false as const, error: "That preset didn't start, and restoring your previous setup also failed — please contact support." };
      });
      if (!outcome.ok) return { error: outcome.error };
    }
  } catch (e) {
    console.error("[free-minecraft] preset apply failed:", e);
    return { error: "Couldn't apply that preset — please try again." };
  }

  const now = new Date();
  await db.freeMinecraftServer.update({
    where: { id: row.id },
    data: { activeGameType: gameType, activeGameMode: gameMode, preset: presetKey },
  });
  await db.freeMinecraftWorld.upsert({
    where: { serverId_gameType: { serverId: row.id, gameType } },
    update: { lastPlayedAt: now },
    create: { serverId: row.id, gameType, label: gameTypeDef.label, lastPlayedAt: now },
  });
  revalidatePath("/dashboard/free-minecraft");
  return {};
}

"use server";

/**
 * Free Minecraft servers — one per verified account, running as a Docker
 * container on the dedicated "freemc-host" VM behind itzg/mc-router (hostname
 * -based routing + auto-scale up/down on connect/idle — see FreeMinecraftServer
 * in prisma/schema.prisma for the full architecture note).
 *
 * KNOWN GAP: disk usage is NOT hard-quota-enforced yet (Docker's storage-opt
 * quota needs XFS+pquota, which this host's filesystem doesn't have). The RAM
 * cap (Docker --memory, a real hard ceiling) and the total-server-count cap are
 * the enforced safety controls for now; `free_minecraft_disk_mb` exists for a
 * future periodic `du`-based sweep, not wired to anything yet.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { assertEmailVerified } from "./email-verification";
import { checkRateLimit } from "./rate-limit";
import { getSettingBool, getSettingInt, getSetting } from "./settings";
import { withServerSsh, exec, shellQuote } from "./ssh-exec";
import type { SftpServer } from "./sftp";
import { validateRconCommand } from "./game-control";
import { schemaFor, validateConfig } from "./game-config";
import {
  getFreeServerStatus,
  getFreeServerPlayers,
  sendRcon,
  readServerProperties,
  writeServerProperties,
  liveRconCommandFor,
  FREEMC_GAME_TYPES,
  FREEMC_GAME_MODES,
  legacyPresetKeyFor,
  recreateGameTypeContainer,
  applyModeProperties,
} from "./free-minecraft-control";
import { getFreemcHostCapacity, wouldExceedFreemcCapacity } from "./freemc-capacity";
import { validateSubdomainFormat, isSubdomainAvailable } from "./game-subdomain";

type Result = { error?: string };

/**
 * Translates one of the OLD flat FREEMC_PRESETS keys (still the only thing
 * the not-yet-migrated dashboard UI — components/customer/freemc/*.tsx,
 * components/customer/FreeMinecraftPanel.tsx — ever submits) into the new
 * two-axis (gameType, gameMode) shape. The 3 old mode-only keys collapse onto
 * vanilla+that mode (that's exactly what they always meant); every other key
 * is a game type, always paired with survival (the old flat scheme had no
 * concept of "preserve the current mode across a preset switch" — every
 * preset fully specified its own properties, so this reproduces that
 * behavior exactly rather than inventing a new one for legacy callers).
 * Returns null for anything unrecognized.
 */
function mapLegacyPresetKey(key: string): { gameType: string; gameMode: string } | null {
  if (key === "creative" || key === "hardcore" || key === "peaceful") return { gameType: "vanilla", gameMode: key };
  if (FREEMC_GAME_TYPES[key]) return { gameType: key, gameMode: "survival" };
  return null;
}

/** The dedicated Docker host — a real Server row (Server.hostname="freemc-host"),
 *  not a customer VPS. Reused via the same withServerSsh every game/backup
 *  action already uses; this just points it at our own internal box instead. */
async function freemcHost(): Promise<SftpServer> {
  const host = await db.server.findFirst({
    where: { hostname: "freemc-host" },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
  });
  if (!host) throw new Error("Free Minecraft host is not provisioned.");
  return host;
}

export async function getMyFreeMinecraftServer() {
  const user = await requireUser();
  return db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
}

export async function createFreeMinecraftServer(_prev: unknown, formData: FormData): Promise<Result> {
  const user = await requireUser();
  const subdomain = String(formData.get("subdomain") ?? "");

  // Prefer the new two-axis fields (the UI being built in parallel sends
  // these); fall back to the legacy flat `preset` field the current create
  // form (components/customer/FreeMinecraftPanel.tsx) still submits, so
  // account creation keeps working unbroken through the UI migration.
  // Defaults to gameType=vanilla, gameMode=survival either way.
  const gameTypeField = formData.get("gameType");
  const gameModeField = formData.get("gameMode");
  let gameType = "vanilla";
  let gameMode = "survival";
  if (typeof gameTypeField === "string" && FREEMC_GAME_TYPES[gameTypeField]) {
    gameType = gameTypeField;
    if (typeof gameModeField === "string" && FREEMC_GAME_MODES[gameModeField]) gameMode = gameModeField;
  } else {
    const mapped = mapLegacyPresetKey(String(formData.get("preset") ?? "vanilla"));
    if (mapped) ({ gameType, gameMode } = mapped);
  }
  const gameTypeDef = FREEMC_GAME_TYPES[gameType];
  const gameModeDef = FREEMC_GAME_MODES[gameMode];

  if (!(await getSettingBool("free_minecraft_enabled", false))) {
    return { error: "Free Minecraft servers aren't open yet — check back soon." };
  }

  try {
    await assertEmailVerified(user);
  } catch {
    return { error: "Verify your email first — check your inbox for the link." };
  }

  const rl = checkRateLimit(`freemc:create:${user.id}`, { max: 5, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };

  const sub = subdomain.trim().toLowerCase();
  const subdomainError = validateSubdomainFormat(sub);
  if (subdomainError) return { error: subdomainError };
  if (!(await isSubdomainAvailable(sub))) return { error: "That name is taken — try another." };

  const existing = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (existing) return { error: "You already have a free server. Delete it before creating another." };

  // `free_minecraft_max_concurrent` (lib/actions-settings.ts) is documented as
  // "how many free servers may be AWAKE at once" — the host-RAM circuit
  // breaker, independent of how many accounts have ever created one. This
  // USED to be checked against a row count of every non-DELETED
  // FreeMinecraftServer, which counts sleeping (stopped-container) servers
  // identically to running ones — the schema's own comment on `status`
  // explains why the DB can't tell them apart (mc-router owns awake/asleep
  // live, never mirrored back to avoid staleness). Once real accounts filled
  // the row-count cap, EVERY new signup was refused as "at capacity" even
  // when every existing container was asleep and the host was idle — the
  // literal thing this setting exists to prevent (an idle host still
  // rejecting signups). Ask the host what's actually awake instead.
  const maxTotal = await getSettingInt("free_minecraft_max_concurrent", 8);
  try {
    const host = await freemcHost();
    const capacity = await withServerSsh(host, (conn) => getFreemcHostCapacity(conn));
    if (capacity.runningContainers.length >= maxTotal) {
      return { error: "Free servers are at capacity right now — please try again later." };
    }
  } catch (e) {
    console.error("[free-minecraft] live capacity check failed, refusing rather than risking overcommit:", e);
    return { error: "Couldn't check server capacity right now — please try again in a moment." };
  }

  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
  const ramMb = await getSettingInt("free_minecraft_ram_mb", 1024);

  // Derived from userId (unique, known up front) rather than the row's own id,
  // so creation is a single write — no awkward "create with a placeholder,
  // then patch in the real name" two-phase step that could race.
  const containerName = `mc-free-${user.id}`;
  let row;
  try {
    row = await db.freeMinecraftServer.create({
      data: {
        userId: user.id,
        subdomain: sub,
        containerName,
        status: "CREATING",
        activeGameType: gameType,
        activeGameMode: gameMode,
        preset: legacyPresetKeyFor(gameType, gameMode),
      },
    });
  } catch {
    return { error: "That name is taken — try another." };
  }

  try {
    const host = await freemcHost();
    const outcome = await withServerSsh(host, async (conn) => {
      const setup = await exec(conn, `mkdir -p ${shellQuote(`/opt/freemc/servers/${row.id}`)}`, 15_000);
      if (setup.code !== 0) return { ok: false as const, error: setup.stderr || "mkdir failed" };
      return recreateGameTypeContainer(conn, {
        containerName: row.containerName,
        dataPath: `/opt/freemc/servers/${row.id}`,
        subdomain: sub,
        domain,
        ramMb,
        ownerId: user.id,
        gameType: gameTypeDef,
        gameTypeKey: gameType,
        gameMode: gameModeDef,
      });
    });
    if (!outcome.ok) throw new Error(outcome.error);
  } catch (e) {
    // Real, reproduced-live bug this closes: a `waitForServerReady` timeout
    // used to delete only the DB row, leaving the actual container running
    // (it can finish booting seconds after the app gives up — see
    // waitForServerReady's doc comment) — orphaned, invisible to the
    // customer, and still occupying a real capacity slot forever since
    // nothing with a DB row left ever prompts its removal. Best-effort:
    // never let a cleanup failure here mask the real error reported below.
    try {
      const host = await freemcHost();
      await withServerSsh(host, (conn) => exec(conn, `docker rm -f ${shellQuote(containerName)}`, 15_000));
    } catch (cleanupErr) {
      console.error("[free-minecraft] post-failure container cleanup failed:", cleanupErr);
    }
    await db.freeMinecraftServer.delete({ where: { id: row.id } }).catch(() => {});
    console.error("[free-minecraft] create failed:", e);
    // recreateGameTypeContainer's own capacity check (CPU/RAM headroom on the
    // host, stricter than the count-based check above) throws an already
    // customer-safe, specific message — surface it as-is rather than masking
    // it with the generic fallback. A real capacity wall reads very
    // differently to a customer than "something broke, try again" — the
    // latter reads as a random glitch and, confirmed live, led a customer to
    // delete a server that would have created fine moments later once
    // whatever else was using the budget finished booting or went idle.
    // Any other failure (SSH/docker error, etc.) keeps the generic message —
    // those shouldn't leak raw internal error text to the customer.
    const msg = e instanceof Error ? e.message : "";
    if (msg.includes("at capacity")) return { error: msg };
    return { error: "Couldn't start your server — please try again in a moment." };
  }

  await db.freeMinecraftServer.update({ where: { id: row.id }, data: { status: "READY" } });
  await db.freeMinecraftWorld.create({
    data: { serverId: row.id, gameType, label: gameTypeDef.label, lastPlayedAt: new Date() },
  });
  revalidatePath("/dashboard/free-minecraft");
  return {};
}

export async function deleteFreeMinecraftServer(_prev: unknown, _formData: FormData): Promise<Result> {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return { error: "You don't have a free server." };

  try {
    const host = await freemcHost();
    await withServerSsh(host, async (conn) => {
      await exec(conn, `docker rm -f ${shellQuote(row.containerName)}`, 30_000);
      await exec(conn, `rm -rf ${shellQuote(`/opt/freemc/servers/${row.id}`)}`, 15_000);
    });
  } catch (e) {
    console.error("[free-minecraft] delete cleanup failed (row is removed regardless):", e);
  }

  await db.freeMinecraftServer.delete({ where: { id: row.id } });
  revalidatePath("/dashboard/free-minecraft");
  return {};
}

/** Fetch the caller's server plus its live Docker/RCON status in one round
 *  trip. Returns null fields (not an error) when the server is asleep — that's
 *  the normal, common state for a free server nobody's playing on right now. */
export async function getFreeMinecraftDashboard() {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return null;

  let running = false;
  let players: { online: number; max: number } | null = null;
  try {
    const host = await freemcHost();
    const status = await withServerSsh(host, (conn) => getFreeServerStatus(conn, row.containerName));
    running = status.running;
    players = status.players;
  } catch (e) {
    console.error("[free-minecraft] status check failed:", e);
  }

  return { ...row, running, players };
}

/** Power controls. mc-router already starts/stops on connect/idle
 *  automatically — these are the manual overrides (force a restart to apply a
 *  settings change now, or stop it to free the slot without waiting it out). */
export async function startFreeMinecraftServer(_prev: unknown, _formData: FormData): Promise<Result> {

"use server";

/**
 * The two-axis free-Minecraft model: GAME TYPE (which isolated, persistent
 * world — vanilla/skyblock/prison/...) and GAME MODE (survival/hardcore/
