import { cfRequest, cfFindZoneId } from "./cloudflare-dns";
import { getSetting } from "./settings";
/**
 * DNS for PAID Minecraft server subdomains (`<name>.play.nxeon.cloud`).
 *
 * Distinct from lib/cloudflare-dns.ts, which is built for CUSTOMER-supplied
 * Cloudflare tokens against a CUSTOMER's own zone. This module uses Nxeon's
 * own platform token (CLOUDFLARE_DNS_API_TOKEN — already live in production,
 * see worker/hosting.ts's ensureWildcardCert) against Nxeon's own nxeon.cloud
 * zone, and manages SRV records, which lib/cloudflare-dns.ts's CfRecordType
 * doesn't support. It still reuses that module's cfRequest/cfFindZoneId (the
 * generic, token-as-parameter HTTP+auth plumbing) rather than duplicating it.
 *
 * Free-tier Minecraft servers (FreeMinecraftServer) reuse the SAME
 * play.nxeon.cloud domain via one shared wildcard A record + mc-router —
 * this module's exact-name records simply take DNS precedence over that
 * wildcard for the specific names paid customers claim (ordinary DNS
 * specificity, no coordination needed with the free-tier setup).
 *
 * Opt-in + inert, matching ensureWildcardCert's own gating: every export is a
 * silent no-op when CLOUDFLARE_DNS_API_TOKEN isn't set, so this can never
 * become a hard dependency for provisioning, a port-forward save, or a
 * suspend/unsuspend cycle.
 */
let cachedZoneId: string | null | undefined;
function token(): string {
  return String(process.env.CLOUDFLARE_DNS_API_TOKEN ?? "").trim();
}
async function zoneId(): Promise<string | null> {
  if (cachedZoneId !== undefined) return cachedZoneId;
  cachedZoneId = await cfFindZoneId(token(), "nxeon.cloud");
  return cachedZoneId;
}
/** The shared base domain both free and paid Minecraft subdomains live under. */
export async function gameSubdomainBase(): Promise<string> {
  return getSetting("free_minecraft_domain", "play.nxeon.cloud");
}
type SrvRecord = { id: string; type: string; name: string; data?: { priority: number; weight: number; port: number; target: string } };
async function upsertA(zone: string, name: string, ip: string): Promise<void> {
  const existing = await cfRequest<{ id: string }[]>(token(), "GET", `/zones/${zone}/dns_records?type=A&name=${encodeURIComponent(name)}&per_page=5`);
  const body = { type: "A", name, content: ip, ttl: 1, proxied: false };
  if (existing[0]) {
    await cfRequest(token(), "PUT", `/zones/${zone}/dns_records/${existing[0].id}`, body);
  } else {
    await cfRequest(token(), "POST", `/zones/${zone}/dns_records`, body);
  }
}
/**
 * `host` is the bare `<subdomain>.<base>` name. Confirmed live against the
 * Cloudflare API (2026-08-30, throwaway test record, deleted immediately
 * after): unlike A/MX/TXT, Cloudflare wants the FULL prefixed name
 * (`_minecraft._tcp.<host>`) as the top-level `name`, with `data` holding
 * ONLY `{priority, weight, port, target}` — `service`/`proto`/`name` inside
 * `data` (a shape that's floated around in various docs/examples) is
 * REJECTED with "DNS name is invalid" (code 9000). `target` is the A
 * record's own name (`host`), matching the pattern established above.
 */
async function upsertSrv(zone: string, host: string, target: string, port: number): Promise<void> {
  const srvName = `_minecraft._tcp.${host}`;
  const existing = await cfRequest<SrvRecord[]>(token(), "GET", `/zones/${zone}/dns_records?type=SRV&name=${encodeURIComponent(srvName)}&per_page=5`);
  const body = { type: "SRV", name: srvName, data: { priority: 0, weight: 5, port, target } };
  if (existing[0]) {
    await cfRequest(token(), "PUT", `/zones/${zone}/dns_records/${existing[0].id}`, body);
  } else {
    await cfRequest(token(), "POST", `/zones/${zone}/dns_records`, body);
  }
}
/**
 * Create or update the A + SRV pair for `<subdomain>.<base>` -> `ip:port`.
 * Silent no-op if the platform Cloudflare token isn't configured.
